(()=>{
  const html = document.documentElement.outerHTML;
  const re = /html\.scribdassets\.com\/[a-z0-9]+\/images\/(\d+)-[a-f0-9]+\.jpg/g;
  const urls = Array.from(new Set((html.match(re)||[])));
  const out = {n: urls.length, urls: urls};
  const vc = window.__viewContext;
  out.vcType = typeof vc;
  if (vc) { try { out.vcKeys = Object.keys(vc); out.vcLen = JSON.stringify(vc).length } catch(e){ out.vcErr = String(e) } }
  const tm = html.match(/"access_token":"([^"]{20,})"/); out.tokenFound = !!tm; if (tm) out.token = tm[1];
  const fu = html.match(/"format_uuid":"([^"]+)"/); out.formatUuid = fu ? fu[1] : null;
  out.cookie = document.cookie.indexOf('scribd') >= 0 ? 'scribd-cookie-present' : 'no-scribd-cookie';
  const t = document.body.innerText || '';
  out.dl = (t.match(/Download[^\n]{0,80}/g)||[]).slice(0,4);
  out.title = document.title;
  out.pageCount = (html.match(/"page_count":\s*(\d+)/)||[])[1] || null;
  return JSON.stringify(out).slice(0,60000);
})()
